<script setup>
import { ref, onMounted } from 'vue'
const token=ref(localStorage.getItem('cym-admin-token')||''), tab=ref('overview'), menu=ref(false), login=ref({username:'',password:''}), users=ref([]),products=ref([]),orders=ref([]),overview=ref({}), message=ref(''), edit=ref(null)
const blank=()=>({name:'',description:'',image:'',cost:'0',reward:'0',stock:0,active:true,options:[],detail_images:[]})
async function api(path,opts={}) { const response=await fetch('/api'+path,{...opts,headers:{'Content-Type':'application/json',...(token.value?{Authorization:`Bearer ${token.value}`}:{})},body:opts.body?JSON.stringify(opts.body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.message||'操作失败');return data.data??data }
function notice(e){message.value=e?.message||e;setTimeout(()=>message.value='',3000)}
async function refresh(){try{[overview.value,users.value,products.value,orders.value]=await Promise.all(['/admin/overview','/admin/users','/admin/products','/admin/orders'].map(api))}catch(e){notice(e)}}
async function signIn(){try{const result=await api('/admin/login',{method:'POST',body:login.value});token.value=result.token;localStorage.setItem('cym-admin-token',result.token);await refresh()}catch(e){notice(e)}}
function signOut(){token.value='';localStorage.removeItem('cym-admin-token')}
function go(value){tab.value=value;menu.value=false}
async function save(){try{const body={...edit.value,options:typeof edit.value.options==='string'?JSON.parse(edit.value.options||'[]'):edit.value.options,detail_images:typeof edit.value.detail_images==='string'?JSON.parse(edit.value.detail_images||'[]'):edit.value.detail_images};await api('/admin/products'+(edit.value.id?'/'+edit.value.id:''),{method:edit.value.id?'PUT':'POST',body});edit.value=null;notice('商品已保存');await refresh()}catch(e){notice(e)}}
async function topup(user){const amount=window.prompt(`为 ${user.username} 充值产品券数量`);if(!amount)return;try{await api('/admin/users/'+user.id+'/topup',{method:'POST',body:{amount,request_id:crypto.randomUUID()}});notice('充值成功');await refresh()}catch(e){notice(e)}}
async function toggleUser(user){try{await api('/admin/users/'+user.id+'/status',{method:'PUT',body:{status:user.status==='active'?'disabled':'active'}});notice('用户状态已更新');await refresh()}catch(e){notice(e)}}
async function arrival(order){const pickup_code=window.prompt('输入提货码',order.pickup_code||'');if(!pickup_code)return;const message=window.prompt('到货留言（可选）',order.pickup_message||'');try{await api('/admin/orders/'+order.id+'/notice',{method:'PUT',body:{pickup_code,message:message||''}});notice('通知已保存');await refresh()}catch(e){notice(e)}}
function modify(p){edit.value={...p,options:typeof p.options==='string'?p.options:JSON.stringify(p.options||[]),detail_images:typeof p.detail_images==='string'?p.detail_images:JSON.stringify(p.detail_images||[])}}
onMounted(()=>{if(token.value)refresh()})
</script>
<template><div v-if="message" class="toast">{{ message }}</div><div v-if="!token" class="login"><section><div class="brand-mark">商</div><h1>商圈管理后台</h1><p>欢迎回来，请登录您的账号</p><input v-model="login.username" placeholder="管理员账号"><input v-model="login.password" type="password" placeholder="密码" @keyup.enter="signIn"><button class="primary" @click="signIn">登录后台</button></section></div><div v-else class="layout"><aside :class="{open:menu}"><div class="brand"><span>商</span><div><b>本地商圈</b><small>运营管理平台</small></div><button class="menu-close" @click="menu=false">×</button></div><nav><button :class="{active:tab==='overview'}" @click="go('overview')">◫　运营概览</button><button :class="{active:tab==='products'}" @click="go('products')">▣　商品管理</button><button :class="{active:tab==='users'}" @click="go('users')">♧　用户管理</button><button :class="{active:tab==='orders'}" @click="go('orders')">▤　订单管理</button></nav><button class="logout" @click="signOut">退出登录</button></aside><div v-if="menu" class="shade" @click="menu=false"></div><div class="content"><header><button class="menu" @click="menu=true">☰</button><div><b>商圈运营中心</b><small>让每一次经营更简单</small></div><button class="refresh" @click="refresh">↻ 刷新数据</button></header><main><section class="intro"><div><small>LOCAL COMMERCE</small><h1>{{ {overview:'运营概览',products:'商品管理',users:'用户管理',orders:'订单管理'}[tab] }}</h1><p>本地商圈 · 运营管理平台</p></div><button v-if="tab==='products'" class="primary" @click="edit=blank()">＋ 添加商品</button></section>
<template v-if="tab==='overview'"><div class="metrics"><article><span>成交订单</span><strong>{{ overview.order_count || 0 }}</strong><small>累计订单</small></article><article><span>产品券消耗</span><strong>{{ overview.total_cost || '0.00' }}</strong><small>累计消耗</small></article><article><span>商圈收益</span><strong>{{ overview.total_reward || '0.00' }}</strong><small>累计发放</small></article><article><span>商圈用户</span><strong>{{ users.length }}</strong><small>用户总数</small></article></div><section class="panel"><h2>最近成交</h2><div v-for="o in orders.slice(0,5)" :key="o.id" class="row"><div><b>{{ o.product_name }}</b><small>{{ o.order_no }}</small></div><div><b>{{ o.cost }} 券</b><small>{{ o.username }}</small></div></div><p v-if="!orders.length" class="empty">暂无成交订单</p></section></template>
<template v-if="tab==='users'"><section class="panel"><h2>用户列表 <small>{{ users.length }} 人</small></h2><div v-for="u in users" :key="u.id" class="item"><div class="item-main"><b>{{ u.username }}</b><small>{{ u.phone }} · ID {{ u.id }} · {{ u.status==='active'?'正常':'已停用' }} <span v-if="u.is_root">· 根账户</span></small></div><div><span>余额</span><b>{{ u.balance }} 券</b></div><div><span>复购</span><b>{{ u.purchase_count }} 次</b></div><div><button class="outline" @click="topup(u)">充值</button><button v-if="!u.is_root" class="outline" @click="toggleUser(u)">{{ u.status==='active'?'停用':'启用' }}</button></div></div><p v-if="!users.length" class="empty">暂无用户</p></section></template>
<template v-if="tab==='products'"><section class="panel"><h2>商圈商品 <small>{{ products.length }} 件</small></h2><div v-for="p in products" :key="p.id" class="item"><div class="item-main"><b>{{ p.name }}</b><small>{{ p.active?'已上架':'已下架' }} · 库存 {{ p.stock }}</small></div><div><span>消耗</span><b>{{ p.cost }} 券</b></div><div><span>收益</span><b>{{ p.reward }} 券</b></div><button class="outline" @click="modify(p)">编辑</button></div><p v-if="!products.length" class="empty">暂无商品，请添加</p></section></template>
<template v-if="tab==='orders'"><section class="panel"><h2>商圈订单 <small>{{ orders.length }} 笔</small></h2><div v-for="o in orders" :key="o.id" class="order"><div class="row"><div><b>{{ o.product_name }}</b><small>{{ o.order_no }} · {{ o.username }} {{ o.phone }}</small></div><b>{{ o.cost }} 券</b></div><div class="order-facts"><span>第 {{ o.purchase_sequence }} 次购买</span><span>收益 {{ o.reward }} 券</span><span>收益去向 {{ o.reward_destination==='root'?'根账户':o.recipient_name }}</span><span>状态 {{ o.status }}</span></div><p v-if="o.pickup_code">提货码：{{ o.pickup_code }} {{ o.pickup_message }}</p><button class="outline" @click="arrival(o)">到货通知</button></div><p v-if="!orders.length" class="empty">暂无订单</p></section></template>
</main></div><div v-if="edit" class="overlay" @click.self="edit=null"><section class="dialog"><header><h2>{{ edit.id?'编辑商品':'添加商品' }}</h2><button @click="edit=null">×</button></header><div class="form"><label>商品名称<input v-model="edit.name"></label><label>商品描述<textarea v-model="edit.description"></textarea></label><label>图片链接<input v-model="edit.image" placeholder="https://..."></label><div class="form-grid"><label>消耗产品券<input v-model="edit.cost" type="number" step="0.01"></label><label>收益产品券<input v-model="edit.reward" type="number" step="0.01"></label><label>库存<input v-model="edit.stock" type="number"></label></div><label>款式 JSON（例如 [{"id":"a","label":"款式一"}]）<textarea v-model="edit.options"></textarea></label><label>详情图片链接 JSON<textarea v-model="edit.detail_images"></textarea></label><label><input v-model="edit.active" type="checkbox"> 上架</label><button class="primary" @click="save">保存商品</button></div></section></div></div></template>
